import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsVisitorUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsVisitorUser";

/**
 * Test successful visitor account registration on politicsBBS discussion board.
 *
 * This test validates the complete visitor authentication flow:
 *
 * 1. Creates visitor account with valid username/password
 * 2. Verifies response contains proper visitor details
 * 3. Validates JWT token is generated for session management
 * 4. Ensures timestamps are created correctly
 * 5. Confirms proper authorization header is set
 *
 * The visitor account enables temporary guest access to political discourse
 * with limited JWT tokens for session continuity while maintaining anonymity.
 */
export async function test_api_visitor_registration_success(
  connection: api.IConnection,
) {
  // Generate test data with valid format constraints
  const visitorData = {
    username: RandomGenerator.alphaNumeric(10) satisfies string &
      tags.MinLength<3> &
      tags.MaxLength<20> &
      tags.Pattern<"^[a-zA-Z0-9-]+$">,
    password: RandomGenerator.alphaNumeric(12) satisfies string &
      tags.MinLength<8> &
      tags.Pattern<"^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).*$">,
    href: "https://politicsbbs.example.com/discussion",
    referrer: "https://news.example.com/politics",
  } satisfies IPoliticsBbsVisitorUser.IJoin;

  // Test successful visitor registration
  const visitor = await api.functional.auth.visitor.join(connection, {
    body: visitorData,
  });

  // Validate response structure matches expected authorization format
  typia.assert(visitor);

  // Verify essential visitor account fields
  TestValidator.equals("visitor id is valid UUID", visitor.id, visitor.id);
  TestValidator.equals(
    "username matches registration",
    visitor.username,
    visitorData.username,
  );
  TestValidator.equals(
    "password_hash exists",
    typeof visitor.password_hash,
    "string",
  );

  // Validate timestamps are properly formatted
  TestValidator.predicate(
    "creation timestamp is valid",
    visitor.created_at.includes("T"),
  );
  TestValidator.predicate(
    "last seen timestamp is valid",
    visitor.last_seen_at.includes("T"),
  );

  // Verify JWT token structure and validity
  TestValidator.equals(
    "access token exists",
    typeof visitor.token.access,
    "string",
  );
  TestValidator.equals(
    "refresh token exists",
    typeof visitor.token.refresh,
    "string",
  );
  TestValidator.predicate(
    "expired_at is date-time format",
    visitor.token.expired_at.includes("T"),
  );
  TestValidator.predicate(
    "refreshable_until is date-time format",
    visitor.token.refreshable_until.includes("T"),
  );

  // Check that connection headers are updated with authorization token
  TestValidator.predicate(
    "authorization header set",
    connection.headers?.Authorization === visitor.token.access,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsVisitorUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsVisitorUser";

/**
 * Test visitor registration duplicate username rejection
 *
 * This test validates that the politicsBBS visitor registration system properly
 * rejects duplicate usernames. The test follows this flow:
 *
 * 1. Create an initial visitor account with unique credentials
 * 2. Attempt to create a second visitor account with the same username
 * 3. Verify that the duplicate username attempt fails with appropriate error
 *
 * The test ensures username uniqueness enforcement in the visitor registration
 * system while maintaining proper request body structure and type safety.
 */
export async function test_api_visitor_registration_duplicate_username(
  connection: api.IConnection,
) {
  // Step 1: Create initial visitor account with unique username
  const visitorUsername = typia.random<
    string &
      tags.MinLength<3> &
      tags.MaxLength<20> &
      tags.Pattern<"^[a-zA-Z0-9-]+$">
  >();
  const initialVisitor = await api.functional.auth.visitor.join(connection, {
    body: {
      username: visitorUsername,
      password: typia.random<
        string &
          tags.MinLength<8> &
          tags.Pattern<"^(?=.*[a-z])(?=.*[A-Z])(?=.*\\\\d).*$">
      >(),
      href: "https://politicsbbs.example.com/register",
      referrer: "https://politicsbbs.example.com/home",
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IPoliticsBbsVisitorUser.IJoin,
  });
  typia.assert(initialVisitor);

  // Step 2: Attempt to create duplicate visitor account with same username
  await TestValidator.error(
    "duplicate username should be rejected",
    async () => {
      await api.functional.auth.visitor.join(connection, {
        body: {
          username: visitorUsername, // Same username - should fail
          password: typia.random<
            string &
              tags.MinLength<8> &
              tags.Pattern<"^(?=.*[a-z])(?=.*[A-Z])(?=.*\\\\d).*$">
          >(),
          href: "https://politicsbbs.example.com/register",
          referrer: "https://politicsbbs.example.com/home",
          ip: typia.random<string & tags.Format<"ipv4">>(),
        } satisfies IPoliticsBbsVisitorUser.IJoin,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsUser";
import type { IPoliticsBbsVisitorUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsVisitorUser";

export async function test_api_visitor_token_refresh_invalid(
  connection: api.IConnection,
) {
  // Step 1: Create a valid visitor account to understand token structure
  const validVisitor = await api.functional.auth.visitor.join(connection, {
    body: {
      href: "https://example.com/visitor/join",
      referrer: "https://example.com/referrer",
      username: typia.random<
        string &
          tags.MinLength<3> &
          tags.MaxLength<20> &
          tags.Pattern<"^[a-zA-Z0-9-]+$">
      >(),
      password: typia.random<
        string &
          tags.MinLength<8> &
          tags.Pattern<"^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).*$">
      >(),
    } satisfies IPoliticsBbsVisitorUser.IJoin,
  });
  typia.assert(validVisitor);

  // Step 2: Test with completely invalid/malformed token (random string)
  await TestValidator.error(
    "refresh with invalid token format should fail",
    async () => {
      await api.functional.auth.visitor.refresh(connection, {
        body: {
          refresh_token: RandomGenerator.alphaNumeric(32),
        } satisfies IPoliticsBbsUser.IRefresh,
      });
    },
  );

  // Step 3: Test with empty token
  await TestValidator.error(
    "refresh with empty token should fail",
    async () => {
      await api.functional.auth.visitor.refresh(connection, {
        body: {
          refresh_token: "",
        } satisfies IPoliticsBbsUser.IRefresh,
      });
    },
  );

  // Step 4: Test with null token (not allowed by types, but API might handle)
  // Note: This test shows intent even if TypeScript prevents it

  // Step 5: Test with token from theoretically expired session (manipulated token)
  const expiredToken =
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpZCI6ImV4cGlyZWQiLCJleHAiOjE2Mzc2NjQwMDB9.invalid";
  await TestValidator.error(
    "refresh with expired token should fail",
    async () => {
      await api.functional.auth.visitor.refresh(connection, {
        body: {
          refresh_token: expiredToken,
        } satisfies IPoliticsBbsUser.IRefresh,
      });
    },
  );

  // Step 6: Test with valid format but invalid internal structure
  const validJWT = `${RandomGenerator.alphaNumeric(20)}.${RandomGenerator.alphaNumeric(20)}.${RandomGenerator.alphaNumeric(20)}`;
  await TestValidator.error(
    "refresh with invalid JWT structure should fail",
    async () => {
      await api.functional.auth.visitor.refresh(connection, {
        body: {
          refresh_token: validJWT,
        } satisfies IPoliticsBbsUser.IRefresh,
      });
    },
  );

  // Verify that valid token still works (basic security check)
  const validRefresh = await api.functional.auth.visitor.refresh(connection, {
    body: {
      refresh_token: validVisitor.token.refresh,
    } satisfies IPoliticsBbsUser.IRefresh,
  });
  typia.assert(validRefresh);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";

/**
 * Test successful token refresh for authenticated member.
 *
 * This test validates that members can exchange valid refresh tokens for new
 * access tokens without re-authentication, maintaining seamless session
 * continuity. The test verifies JWT token expiration is properly updated and
 * members can continue accessing protected features like article creation and
 * commenting with new tokens.
 *
 * Test workflow:
 *
 * 1. Create member account to generate initial refresh token
 * 2. Verify tokens received from registration
 * 3. Use refresh token to get new access token
 * 4. Validate new authorization token structure
 * 5. Verify old refresh token doesn't work (security check)
 * 6. Test concurrent operations with new token
 */
export async function test_api_member_token_refresh_success(
  connection: api.IConnection,
) {
  // Step 1: Create member account and obtain initial tokens
  const username = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<20>
  >();
  const email = typia.random<string & tags.Format<"email">>();

  const member: IPoliticsBbsMember.IAuthorized =
    await api.functional.auth.members.join(connection, {
      body: {
        username,
        email,
        password: "TestPass123",
        href: "https://example.com/join",
        referrer: "https://example.com/home",
      } satisfies IPoliticsBbsMember.IJoin,
    });

  typia.assert(member);

  // Validate initial token structure
  TestValidator.predicate(
    "member has valid token",
    member.token !== undefined &&
      member.token.access !== undefined &&
      member.token.refresh !== undefined,
  );

  TestValidator.predicate(
    "token has expiration",
    member.token.expired_at !== undefined &&
      member.token.refreshable_until !== undefined,
  );

  const originalToken = member.token;

  // Step 2: Wait a moment to ensure token timestamps change
  await new Promise((resolve) => setTimeout(resolve, 100));

  // Step 3: Use refresh token to get new access token
  const refreshedMember: IPoliticsBbsMember.IAuthorized =
    await api.functional.auth.members.refresh(connection, {
      body: {
        refresh_token: originalToken.refresh,
      } satisfies IPoliticsBbsMember.IRefresh,
    });

  typia.assert(refreshedMember);

  // Step 4: Validate refreshed token structure
  TestValidator.predicate(
    "refreshed member has valid token",
    refreshedMember.token !== undefined &&
      refreshedMember.token.access !== undefined &&
      refreshedMember.token.refresh !== undefined,
  );

  TestValidator.predicate(
    "token attributes match",
    refreshedMember.id === member.id &&
      refreshedMember.username === member.username &&
      refreshedMember.email === member.email,
  );

  TestValidator.predicate(
    "new access token is different",
    refreshedMember.token.access !== originalToken.access,
  );

  TestValidator.notEquals(
    "new refresh token differs",
    refreshedMember.token.refresh,
    originalToken.refresh,
  );

  TestValidator.predicate(
    "new expiration is updated",
    refreshedMember.token.expired_at > originalToken.expired_at,
  );

  // Step 5: Validate new authorization header is set
  TestValidator.predicate(
    "connection has authorization header",
    connection.headers !== undefined &&
      connection.headers.Authorization !== undefined &&
      connection.headers.Authorization === refreshedMember.token.access,
  );

  // Step 6: Test that old refresh token no longer works
  await TestValidator.error("old refresh token should expire", async () => {
    await api.functional.auth.members.refresh(connection, {
      body: {
        refresh_token: originalToken.refresh,
      } satisfies IPoliticsBbsMember.IRefresh,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
