export async function test_api_member_registration_success(
  connection: api.IConnection,
) {
  // Generate valid test data following the DTO constraints
  const username = `${RandomGenerator.alphaNumeric(7)}-user`;
  const email = `${RandomGenerator.alphaNumeric(6)}-${new Date().getTime()}@test.example.com`;
  const password = "TestPassword123456";
  const href = "https://example.com/auth/join";
  const referrer = "https://example.com/";

  // Create registration request without type annotation - satisfies handles type safety
  const joinData = {
    username,
    email,
    password,
    href,
    referrer,
  } satisfies IPoliticsBbsMember.IJoin;

  // Call member registration API - MUST HAVE AWAIT
  const member = await api.functional.auth.members.join(connection, {
    body: joinData,
  });

  // Validate the complete response structure
  typia.assert(member);

  // Validate core member data with proper TestValidator titles
  TestValidator.equals(
    "registered username matches input",
    member.username,
    username,
  );
  TestValidator.equals("registered email matches input", member.email, email);
  TestValidator.equals("member role should be 'member'", member.role, "member");
  TestValidator.predicate("member ID should be valid UUID", !!member.id);

  // Validate timestamps are properly set
  TestValidator.predicate("created_at should be set", !!member.created_at);
  TestValidator.predicate("updated_at should be set", !!member.updated_at);
  TestValidator.equals(
    "deleted_at should be null for active account",
    member.deleted_at,
    null,
  );

  // Validate authorization structure
  const token = member.token;
  TestValidator.predicate("access token must be present", !!token.access);
  TestValidator.predicate("refresh token must be present", !!token.refresh);

  // Validate token expiration timestamps
  TestValidator.predicate("expired_at must be present", !!token.expired_at);
  TestValidator.predicate(
    "refreshable_until must be present",
    !!token.refreshable_until,
  );

  // Validate timestamps are in ISO datetime format
  TestValidator.predicate(
    "created_at must be valid ISO datetime",
    !!member.created_at?.includes("T"),
  );
  TestValidator.predicate(
    "updated_at must be valid ISO datetime",
    !!member.updated_at?.includes("T"),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";

/**
 * Test member registration failure when attempting to register with a username
 * that already exists.
 */
export async function test_api_member_registration_duplicate_username(
  connection: api.IConnection,
) {
  // Step 1: Create initial member account to establish duplicate username scenario
  const firstMemberData = {
    username: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
    href: `https://example.com/register`,
    referrer: `https://example.com/home`,
  } satisfies IPoliticsBbsMember.IJoin;

  const firstMember: IPoliticsBbsMember.IAuthorized =
    await api.functional.auth.members.join(connection, {
      body: firstMemberData,
    });
  typia.assert(firstMember);

  // Step 2: Attempt to register another member with the same username
  // This should fail due to duplicate username
  const duplicateMemberData = {
    username: firstMemberData.username, // Same username as first member
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
    href: `https://example.com/register`,
    referrer: `https://example.com/home`,
  } satisfies IPoliticsBbsMember.IJoin;

  await TestValidator.error(
    "duplicate username registration should fail",
    async () => {
      await api.functional.auth.members.join(connection, {
        body: duplicateMemberData,
      });
    },
  );

  // Step 3: Verify that the duplicate registration attempt failed as expected
  TestValidator.equals(
    "original member still exists with correct username",
    firstMember.username,
    firstMemberData.username,
  );

  // Attempting to register another member even with different email but same username should fail
  await TestValidator.error(
    "duplicate username with different email should still fail",
    async () => {
      await api.functional.auth.members.join(connection, {
        body: {
          username: firstMemberData.username,
          email: typia.random<string & tags.Format<"email">>(), // Different email
          password: RandomGenerator.alphaNumeric(10),
          href: `https://example.com/register`,
          referrer: `https://example.com/home`,
        } satisfies IPoliticsBbsMember.IJoin,
      });
    },
  );
}

