import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";

/**
 * Test member registration workflow completion.
 *
 * This test validates the system's ability to handle concurrent user
 * registrations and maintain proper user account isolation. The test creates
 * multiple member accounts with unique credentials to ensure the registration
 * endpoint can handle multiple successful registrations while maintaining data
 * integrity and uniqueness constraints.
 *
 * Test Steps:
 *
 * 1. Generate unique credentials for multiple member accounts
 * 2. Register each member account with valid data
 * 3. Verify all registrations succeed and return proper authorization
 * 4. Validate response data structure and token generation
 * 5. Test duplicate username/email prevention (error case)
 */
export async function test_api_member_registration_workflow(
  connection: api.IConnection,
) {
  const testMembers: IPoliticsBbsMember.IAuthorized[] = [];

  // Create multiple test members with unique credentials
  for (let i = 0; i < 5; i++) {
    const usernameLengths = [3, 4, 5, 6] as const;
    const usernameLength = RandomGenerator.pick(usernameLengths);
    const username = RandomGenerator.alphabets(usernameLength);
    const email = `user${i}_${RandomGenerator.alphabets(5)}@test.com`;
    const password = RandomGenerator.alphaNumeric(8);

    const joinData = {
      username: username,
      email: email,
      password: password,
      href: "https://localhost:3000/register",
      referrer: "https://localhost:3000/signup",
    } satisfies IPoliticsBbsMember.IJoin;

    const member = await api.functional.auth.members.join(connection, {
      body: joinData,
    });

    typia.assert(member);
    TestValidator.equals(
      "username matches creation request",
      member.username,
      username,
    );
    TestValidator.equals("email matches creation request", member.email, email);
    TestValidator.predicate("member has valid ID format", member.id.length > 0);
    TestValidator.predicate(
      "token access is provided",
      member.token.access.length > 0,
    );
    TestValidator.predicate(
      "token refresh is provided",
      member.token.refresh.length > 0,
    );
    TestValidator.predicate(
      "token has expiration",
      member.token.expired_at.length > 0,
    );
    TestValidator.predicate(
      "token is refreshable",
      member.token.refreshable_until.length > 0,
    );
    TestValidator.equals("member role is member", member.role, "member");

    testMembers.push(member);
  }

  // Verify all members have unique data
  TestValidator.equals(
    "all usernames are unique",
    new Set(testMembers.map((m) => m.username)).size,
    testMembers.length,
  );
  TestValidator.equals(
    "all emails are unique",
    new Set(testMembers.map((m) => m.email)).size,
    testMembers.length,
  );
  TestValidator.equals(
    "all IDs are unique",
    new Set(testMembers.map((m) => m.id)).size,
    testMembers.length,
  );

  // Test duplicate registration prevention
  await TestValidator.error(
    "duplicate username registration should fail",
    async () => {
      await api.functional.auth.members.join(connection, {
        body: {
          username: testMembers[0].username,
          email: `new_${RandomGenerator.alphabets(6)}@test.com`,
          password: RandomGenerator.alphaNumeric(8),
          href: "https://localhost:3000/register",
          referrer: "https://localhost:3000/signup",
        } satisfies IPoliticsBbsMember.IJoin,
      });
    },
  );

  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      await api.functional.auth.members.join(connection, {
        body: {
          username: RandomGenerator.alphabets(6),
          email: testMembers[0].email,
          password: RandomGenerator.alphaNumeric(8),
          href: "https://localhost:3000/register",
          referrer: "https://localhost:3000/signup",
        } satisfies IPoliticsBbsMember.IJoin,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";

/**
 * Test successful member login with valid username and password credentials.
 *
 * This test validates the complete member authentication flow by:
 *
 * 1. Creating a new member account through the registration endpoint
 * 2. Authenticating the member with valid login credentials
 * 3. Verifying that JWT access and refresh tokens are properly issued
 * 4. Confirming that the authenticated member data matches the expected structure
 *
 * The test ensures the system correctly validates credentials against stored
 * password hash, verifies account existence and active status (not
 * soft-deleted), and provides proper JWT tokens for accessing member-only
 * features like article creation, commenting, and file uploads on the politics
 * discussion board.
 */
export async function test_api_member_login_success(
  connection: api.IConnection,
) {
  // Generate random test data for member registration
  const joinData = {
    username: typia.random<
      string &
        tags.MinLength<3> &
        tags.MaxLength<20> &
        tags.Pattern<"^[a-zA-Z0-9-]+$">
    >(),
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    href: "https://example.com/join",
    referrer: "https://example.com/home",
  } satisfies IPoliticsBbsMember.IJoin;

  // Step 1: Create member account for login testing
  const registeredMember: IPoliticsBbsMember.IAuthorized =
    await api.functional.auth.members.join(connection, { body: joinData });
  typia.assert(registeredMember);

  // Verify registration was successful
  TestValidator.equals(
    "registered member username",
    registeredMember.username,
    joinData.username,
  );
  TestValidator.equals(
    "registered member email",
    registeredMember.email,
    joinData.email,
  );
  TestValidator.predicate(
    "member has member role",
    registeredMember.role === "member" || registeredMember.role === undefined,
  );
  TestValidator.predicate(
    "member has valid ID format",
    typia.is<string & tags.Format<"uuid">>(registeredMember.id),
  );
  TestValidator.predicate(
    "member has password hash",
    registeredMember.password_hash.length > 0,
  );
  TestValidator.predicate(
    "member has valid timestamps",
    typia.is<string & tags.Format<"date-time">>(registeredMember.created_at) &&
      typia.is<string & tags.Format<"date-time">>(registeredMember.updated_at),
  );
  TestValidator.predicate(
    "member is not deleted",
    registeredMember.deleted_at === null ||
      registeredMember.deleted_at === undefined,
  );

  // Step 2: Test successful login with valid credentials
  const loginData = {
    username: joinData.username,
    password: joinData.password,
    href: "https://example.com/login",
    referrer: "https://example.com/join",
  } satisfies IPoliticsBbsMember.ILogin;

  const authenticatedMember: IPoliticsBbsMember.IAuthorized =
    await api.functional.auth.members.login(connection, { body: loginData });
  typia.assert(authenticatedMember);

  // Step 3: Verify login response matches expected structure and data
  TestValidator.equals(
    "authenticated member ID matches",
    authenticatedMember.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "authenticated member username matches",
    authenticatedMember.username,
    registeredMember.username,
  );
  TestValidator.equals(
    "authenticated member email matches",
    authenticatedMember.email,
    registeredMember.email,
  );
  TestValidator.equals(
    "authenticated member password hash matches",
    authenticatedMember.password_hash,
    registeredMember.password_hash,
  );
  TestValidator.equals(
    "authenticated member timestamps match",
    authenticatedMember.created_at,
    registeredMember.created_at,
  );
  TestValidator.equals(
    "authenticated member role matches",
    authenticatedMember.role,
    registeredMember.role,
  );
  TestValidator.equals(
    "authenticated member deletion status matches",
    authenticatedMember.deleted_at,
    registeredMember.deleted_at,
  );

  // Step 4: Verify JWT tokens are properly issued
  TestValidator.predicate(
    "member has authorization token",
    authenticatedMember.token !== null &&
      authenticatedMember.token !== undefined,
  );
  TestValidator.predicate(
    "token has access token",
    authenticatedMember.token.access.length > 0,
  );
  TestValidator.predicate(
    "token has refresh token",
    authenticatedMember.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "token has expiration timestamp",
    typia.is<string & tags.Format<"date-time">>(
      authenticatedMember.token.expired_at,
    ),
  );
  TestValidator.predicate(
    "token has refreshable timestamp",
    typia.is<string & tags.Format<"date-time">>(
      authenticatedMember.token.refreshable_until,
    ),
  );

  // Step 5: Verify token expiration logic
  const expiredAt = new Date(authenticatedMember.token.expired_at);
  const refreshableUntil = new Date(
    authenticatedMember.token.refreshable_until,
  );
  const now = new Date();

  TestValidator.predicate("access token expires in future", expiredAt > now);
  TestValidator.predicate(
    "refresh token expires after access token",
    refreshableUntil > expiredAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";

/**
 * Test complete authentication workflow from registration to login. Verify that
 * a newly registered member can successfully authenticate using their
 * credentials, demonstrating the full user onboarding and authentication
 * cycle.
 */
export async function test_api_member_authentication_workflow(
  connection: api.IConnection,
) {
  // Step 1: Generate test data for member registration
  const username = RandomGenerator.alphaNumeric(8);
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const joinData = {
    username,
    email,
    password,
    href: "https://example.com/register",
    referrer: "https://example.com/login",
  } satisfies IPoliticsBbsMember.IJoin;

  // Step 2: Register new member account
  const registeredMember = await api.functional.auth.members.join(connection, {
    body: joinData,
  });
  typia.assert(registeredMember);

  // Step 3: Validate registration response with complete field verification
  TestValidator.equals(
    "registered member username matches input",
    registeredMember.username,
    username,
  );
  TestValidator.equals(
    "registered member email matches input",
    registeredMember.email,
    email,
  );
  TestValidator.predicate("member has valid UUID id", () =>
    typia.is<string & tags.Format<"uuid">>(registeredMember.id),
  );
  TestValidator.predicate(
    "member has JWT token",
    () => registeredMember.token.access.length > 0,
  );
  TestValidator.predicate("member token has expiration", () =>
    typia.is<string & tags.Format<"date-time">>(
      registeredMember.token.expired_at,
    ),
  );
  TestValidator.predicate(
    "member token has refresh token",
    () => registeredMember.token.refresh.length > 0,
  );
  TestValidator.predicate("member token has refresh expiration", () =>
    typia.is<string & tags.Format<"date-time">>(
      registeredMember.token.refreshable_until,
    ),
  );
  TestValidator.predicate("member has created_at timestamp", () =>
    typia.is<string & tags.Format<"date-time">>(registeredMember.created_at),
  );
  TestValidator.predicate("member has updated_at timestamp", () =>
    typia.is<string & tags.Format<"date-time">>(registeredMember.updated_at),
  );
  TestValidator.predicate(
    "member has password hash",
    () => registeredMember.password_hash.length > 0,
  );
  TestValidator.predicate(
    "member has correct role",
    () => registeredMember.role === "member",
  );
  TestValidator.predicate(
    "member is not deleted",
    () =>
      registeredMember.deleted_at === undefined ||
      registeredMember.deleted_at === null,
  );

  // Step 4: Verify connection headers are set after registration (authentication state)
  TestValidator.predicate(
    "connection has authorization header after registration",
    () => {
      const headers = connection.headers ?? {};
      return headers.Authorization === registeredMember.token.access;
    },
  );

  // Step 5: Attempt login with same credentials
  const loginData = {
    username,
    password,
    href: "https://example.com/login",
    referrer: "https://example.com/register",
  } satisfies IPoliticsBbsMember.ILogin;

  const authenticatedMember = await api.functional.auth.members.login(
    connection,
    { body: loginData },
  );
  typia.assert(authenticatedMember);

  // Step 6: Validate login response matches registration data comprehensively
  TestValidator.equals(
    "authenticated member id matches registered member",
    authenticatedMember.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "authenticated member username matches registered member",
    authenticatedMember.username,
    registeredMember.username,
  );
  TestValidator.equals(
    "authenticated member email matches registered member",
    authenticatedMember.email,
    registeredMember.email,
  );
  TestValidator.equals(
    "authenticated member password hash matches",
    authenticatedMember.password_hash,
    registeredMember.password_hash,
  );
  TestValidator.equals(
    "authenticated member created_at matches",
    authenticatedMember.created_at,
    registeredMember.created_at,
  );
  TestValidator.equals(
    "authenticated member updated_at matches",
    authenticatedMember.updated_at,
    registeredMember.updated_at,
  );
  TestValidator.equals(
    "authenticated member role matches",
    authenticatedMember.role,
    registeredMember.role,
  );
  TestValidator.predicate(
    "authenticated member deleted_at matches",
    () => authenticatedMember.deleted_at === registeredMember.deleted_at,
  );
  TestValidator.predicate(
    "authenticated member has new JWT token",
    () => authenticatedMember.token.access.length > 0,
  );
  TestValidator.predicate(
    "new token has different access token",
    () => authenticatedMember.token.access !== registeredMember.token.access,
  );
  TestValidator.predicate(
    "authenticated member token has expiration in future",
    () => {
      const expiredAt = new Date(authenticatedMember.token.expired_at);
      return expiredAt.getTime() > Date.now();
    },
  );

  // Step 7: Verify connection headers are updated after login (new authentication state)
  TestValidator.predicate(
    "connection has updated authorization header after login",
    () => {
      const headers = connection.headers ?? {};
      return headers.Authorization === authenticatedMember.token.access;
    },
  );

  // Step 8: Test authentication with wrong password
  const wrongPasswordData = {
    username,
    password: "wrongpassword123",
    href: "https://example.com/login",
    referrer: "https://example.com/register",
  } satisfies IPoliticsBbsMember.ILogin;

  await TestValidator.error(
    "authentication should fail with wrong password",
    async () => {
      await api.functional.auth.members.login(connection, {
        body: wrongPasswordData,
      });
    },
  );

  // Step 9: Test authentication with non-existent username
  const nonExistentUserData = {
    username: "nonexistentuser12345",
    password,
    href: "https://example.com/login",
    referrer: "https://example.com/register",
  } satisfies IPoliticsBbsMember.ILogin;

  await TestValidator.error(
    "authentication should fail with non-existent username",
    async () => {
      await api.functional.auth.members.login(connection, {
        body: nonExistentUserData,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPoliticsBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticle";
import type { IPoliticsBbsArticleSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticleSnapshot";
import type { IPoliticsBbsAttachmentOfMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfMember";
import type { IPoliticsBbsAttachmentOfModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfModerator";
import type { IPoliticsBbsAttachmentOfVisitor } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfVisitor";
import type { IPoliticsBbsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsCategory";
import type { IPoliticsBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsComment";
import type { IPoliticsBbsFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsFileAttachment";
import type { IPoliticsBbsImageAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsImageAttachment";
import type { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";
import type { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";
import type { IPoliticsBbsVisitor } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsVisitor";

/**
 * Test successful article creation by authenticated member with title, content,
 * and category assignment.
 *
 * This test validates the complete article creation workflow for members
 * including:
 *
 * - Member registration and authentication
 * - Category creation (moderator dependency)
 * - Article creation with title/content validation (5-150 chars title, 50+ chars
 *   content)
 * - Business rule enforcement and state management
 * - Category assignment and article metadata
 *
 * The test ensures all validation constraints are properly enforced and
 * articles are created in the appropriate state for the politics discussion
 * board platform.
 */
export async function test_api_article_creation_by_member(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const username = RandomGenerator.name();
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.members.join(connection, {
    body: {
      username,
      email: memberEmail,
      password: "ValidPassword123",
      ip: "127.0.0.1",
      href: "https://example.com/politics-bbs",
      referrer: "https://example.com/",
    } satisfies IPoliticsBbsMember.IJoin,
  });
  typia.assert(member);

  // Step 2: Create category for article assignment (moderator dependency)
  const categoryCode = `category-${RandomGenerator.alphabets(8)}`;
  const category = await api.functional.politicsBbs.moderator.categories.create(
    connection,
    {
      body: {
        code: categoryCode,
        name: RandomGenerator.name(2),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        color: "#1E88E5",
        icon: "fas fa-users",
        sequence: 1,
        primary: true,
        required: true,
        multiplicative: false,
      } satisfies IPoliticsBbsCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 3: Create article with valid title and content
  const articleTitle = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 3,
    wordMax: 10,
  });
  TestValidator.predicate(
    "article title should be 5-150 characters",
    articleTitle.length >= 5 && articleTitle.length <= 150,
  );

  const articleContent = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 15,
    sentenceMax: 25,
    wordMin: 4,
    wordMax: 8,
  });
  TestValidator.predicate(
    "article content should be minimum 50 characters",
    articleContent.length >= 50,
  );

  const article = await api.functional.politicsBbs.member.articles.create(
    connection,
    {
      body: {
        politics_bbs_category_id: category.id,
        title: articleTitle,
        content: articleContent,
      } satisfies IPoliticsBbsArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 4: Validate article creation
  TestValidator.equals(
    "article has correct category",
    article.politics_bbs_category_id,
    category.id,
  );
  TestValidator.equals(
    "article title matches input",
    article.title,
    articleTitle,
  );
  TestValidator.equals(
    "article content matches input",
    article.content,
    articleContent,
  );

  // Validate article state (should be pending for new articles)
  TestValidator.predicate(
    "article should be in pending state",
    article.state === "pending",
  );

  // Validate initial view count
  TestValidator.equals("article view count starts at 0", article.view_count, 0);

  // Validate creator relationship matches member
  TestValidator.equals(
    "article creator ID matches member",
    article.politics_bbs_creator_id,
    member.id,
  );

  // Validate category relationship is properly set
  TestValidator.predicate(
    "article has associated category",
    article.category !== undefined,
  );
  TestValidator.equals(
    "category ID matches",
    article.category?.id,
    category.id,
  );

  // Step 5: Test business rule validation
  // Try creating article with invalid title length
  const shortTitle = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 2,
    wordMax: 3,
  });
  TestValidator.predicate(
    "short title should be less than 5 characters",
    shortTitle.length < 5,
  );

  await TestValidator.error(
    "article creation should fail with title too short",
    async () => {
      await api.functional.politicsBbs.member.articles.create(connection, {
        body: {
          politics_bbs_category_id: category.id,
          title: shortTitle,
          content: articleContent,
        } satisfies IPoliticsBbsArticle.ICreate,
      });
    },
  );

  // Try creating article with content too short
  const shortContent = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 2,
    wordMax: 4,
  });
  TestValidator.predicate(
    "short content should be less than 50 characters",
    shortContent.length < 50,
  );

  await TestValidator.error(
    "article creation should fail with content too short",
    async () => {
      await api.functional.politicsBbs.member.articles.create(connection, {
        body: {
          politics_bbs_category_id: category.id,
          title: articleTitle,
          content: shortContent,
        } satisfies IPoliticsBbsArticle.ICreate,
      });
    },
  );

  // Step 6: Validate article structure and relationships
  TestValidator.predicate(
    "article should have snapshots array",
    Array.isArray(article.snapshots),
  );
  TestValidator.equals(
    "article should start with one snapshot",
    article.snapshots?.length,
    1,
  );

  if (article.snapshots && article.snapshots.length > 0) {
    const snapshot = article.snapshots[0];
    TestValidator.equals(
      "snapshot title matches article",
      snapshot.title,
      articleTitle,
    );
    TestValidator.equals(
      "snapshot content matches article",
      snapshot.content,
      articleContent,
    );
    TestValidator.equals(
      "snapshot state matches article",
      snapshot.state,
      article.state,
    );
    TestValidator.equals("snapshot view count matches", snapshot.view_count, 0);
  }
}

