  const article = await api.functional.politicsBbs.member.articles.create(
    connection,
    {
      body: {
        politics_bbs_category_id: category.id,
        title: articleTitle,
        content: articleContent,
      } satisfies IPoliticsBbsArticle.ICreate,
    },
