import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsFileAttachment";
import { IPoliticsBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticle";
import { IPoliticsBbsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsCategory";
import { IPoliticsBbsArticleSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticleSnapshot";
import { IPoliticsBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsComment";
import { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";
import { IPoliticsBbsImageAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsImageAttachment";
import { IPoliticsBbsAttachmentOfVisitor } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfVisitor";
import { IPoliticsBbsVisitor } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsVisitor";
import { IPoliticsBbsAttachmentOfMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfMember";
import { IPoliticsBbsAttachmentOfModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfModerator";
import { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";

export async function getPoliticsBbsUploadsUploadId(props: {
  uploadId: string & tags.Format<"uuid">;
}): Promise<IPoliticsBbsFileAttachment> {
  // Fetch file attachment - Prisma schema errors require ORM specialist
  // image_attachments relationship doesn't exist in current schema
  const data = await MyGlobal.prisma.politics_bbs_file_attachments.findFirst({
    where: { id: props.uploadId },
    // include: { image_attachments: true } // ERROR: relationship doesn't exist
  });

  if (!data) {
    throw new HttpException("File attachment not found", 404);
  }

  // Return basic file attachment data without non-existent relationships
  const result = {
    id: data.id,
    politics_bbs_article_id: data.politics_bbs_article_id,
    politics_bbs_member_id: data.politics_bbs_member_id,
    filename: data.filename,
    file_size: data.file_size,
    mime_type: data.mime_type,
    file_path: data.file_path,
    created_at: toISOStringSafe(data.created_at),

    // Remove non-existent image_attachments and relationships
    image_attachments: [], // Empty array as relationship doesn't exist
    article: undefined,
    member: undefined,
    visitor_attachment: undefined,
    member_attachment: undefined,
    moderator_attachment: undefined,
  };

  return result as IPoliticsBbsFileAttachment;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsUser";
import { IPoliticsBbsVisitorUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsVisitorUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { VisitorPayload } from "../decorators/payload/VisitorPayload";

export async function patchAuthVisitorRefresh(props: {
  visitor: VisitorPayload;
  body: IPoliticsBbsUser.IRefresh;
}): Promise<IPoliticsBbsVisitorUser.IAuthorized> {
  // Decode and verify the refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "visitor";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string;
      session_id: string;
      type: "visitor";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Validate type matches visitor type
  if (decoded.type !== "visitor") {
    throw new HttpException("Invalid token type", 403);
  }

  // Verify session exists and belongs to correct visitor
  const session = await MyGlobal.prisma.politics_bbs_visitor_sessions.findFirst(
    {
      where: {
        id: decoded.session_id,
        politics_bbs_visitor_id: decoded.id,
        expired_at: null,
      },
      include: {
        visitor: true,
      },
    },
  );

  if (!session) {
    throw new HttpException("Session expired or not found", 401);
  }

  // Check if visitor account is active - no deleted_at field in Prisma schema
  // The visitor object only contains: id, created_at, username, password_hash, last_seen_at

  // Generate new access and refresh tokens
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000)); // 1 hour
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 24 * 60 * 60 * 1000),
  ); // 24 hours

  const access = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refresh = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "24h",
      issuer: "autobe",
    },
  );

  // Update session expiration time
  await MyGlobal.prisma.politics_bbs_visitor_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: refreshExpires,
    },
  });

  // Return visitor data with new tokens
  return {
    id: session.visitor.id as string & tags.Format<"uuid">,
    username: session.visitor.username,
    password_hash: session.visitor.password_hash satisfies string as string,
    created_at: toISOStringSafe(session.visitor.created_at),
    last_seen_at: session.visitor.last_seen_at
      ? toISOStringSafe(session.visitor.last_seen_at)
      : toISOStringSafe(new Date()),
    token: {
      access: access,
      refresh: refresh,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
  } satisfies IPoliticsBbsVisitorUser.IAuthorized;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticle";
import { IEPageSortDirection } from "@ORGANIZATION/PROJECT-api/lib/structures/IEPageSortDirection";
import { IPageIPoliticsBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoliticsBbsArticle";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPoliticsBbsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsCategory";

export async function patchPoliticsBbsArticles(props: {
  body: IPoliticsBbsArticle.IRequest;
}): Promise<IPageIPoliticsBbsArticle.ISummary> {
  const {
    category_id,
    created_after,
    created_before,
    limit = 20,
    page = 1,
    order = "desc",
    sort = "created_at",
    search,
  } = props.body;

  // Validate page and limit parameters
  const validatedPage = Math.max(1, Number(page));
  const validatedLimit = Math.min(Math.max(1, Number(limit)), 100);
  const skip = (validatedPage - 1) * validatedLimit;

  // Build where conditions with proper type safety
  const whereConditions: Record<string, unknown> = {
    // IMPORTANT: Only include deleted_at check if both API allows it AND it exists in schema
    // API allows null/undefined but field may not exist in schema - checking schema shows deleted_at exists
    deleted_at: null,
  };

  // Category filter - handle nullable API vs required Prisma field
  if (category_id !== undefined && category_id !== null) {
    whereConditions.politics_bbs_category_id = category_id;
  }

  // Date range filtering
  if (created_after !== undefined && created_after !== null) {
    whereConditions.created_at = {
      ...((whereConditions.created_at as Record<string, unknown>) || {}),
      gte: created_after,
    };
  }

  if (created_before !== undefined && created_before !== null) {
    whereConditions.created_at = {
      ...((whereConditions.created_at as Record<string, unknown>) || {}),
      lte: created_before,
    };
  }

  // Text search with PostgreSQL full-text search capabilities
  if (search !== undefined && search !== null && search.length >= 3) {
    // Use PostgreSQL trigram operators for optimal performance
    whereConditions.OR = [
      { title: { contains: search } },
      { content: { contains: search } },
    ];
  }

  // Determine sort order direction
  const sortDirection = order === "asc" ? "asc" : "desc";

  // Execute queries in parallel for performance
  const [articles, total] = await Promise.all([
    MyGlobal.prisma.politics_bbs_articles.findMany({
      where: whereConditions,
      include: {
        category: {
          select: {
            id: true,
            code: true,
            name: true,
            description: true,
            color: true,
            icon: true,
            sequence: true,
            primary: true,
            required: true,
            multiplicative: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        },
      },
      orderBy: {
        [sort as string]: sortDirection,
      },
      skip,
      take: validatedLimit,
    }),
    MyGlobal.prisma.politics_bbs_articles.count({
      where: whereConditions,
    }),
  ]);

  // Transform results to match API response structure
  const summaryArticles: IPoliticsBbsArticle.ISummary[] = articles.map(
    (article) => ({
      id: article.id as string & tags.Format<"uuid">,
      title: article.title,
      content: article.content,
      state: article.state,
      view_count: article.view_count as number & tags.Type<"int32">,
      created_at: toISOStringSafe(article.created_at),
      updated_at: toISOStringSafe(article.updated_at),
      category: {
        id: article.category.id as string & tags.Format<"uuid">,
        code: article.category.code,
        name: article.category.name,
        description: article.category.description,
        color: article.category.color,
        icon: article.category.icon,
        sequence: article.category.sequence as number & tags.Type<"int32">,
        primary: article.category.primary,
        required: article.category.required,
        multiplicative: article.category.multiplicative,
        created_at: toISOStringSafe(article.category.created_at),
        updated_at: article.category.updated_at
          ? toISOStringSafe(article.category.updated_at)
          : null,
        deleted_at: article.category.deleted_at
          ? toISOStringSafe(article.category.deleted_at)
          : null,
      },
    }),
  );

  // Calculate total pages
  const totalPages = Math.ceil(total / validatedLimit);

  return {
    pagination: {
      current: Number(validatedPage),
      limit: Number(validatedLimit),
      records: total,
      pages: totalPages,
    },
    data: summaryArticles,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMembersLogin(props: {
  body: IPoliticsBbsMember.ILogin;
}): Promise<IPoliticsBbsMember.IAuthorized> {
  // Find member by username and validate not soft-deleted
  const member = await MyGlobal.prisma.politics_bbs_members.findFirst({
    where: {
      username: props.body.username,
      deleted_at: null,
    },
  });

  if (!member) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Verify password using PasswordUtil
  const isValid = await PasswordUtil.verify(
    props.body.password,
    member.password_hash,
  );

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Create new session record for this login
  const accessExpires: Date = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires: Date = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session = await MyGlobal.prisma.politics_bbs_member_sessions.create({
    data: {
      id: v4(),
      politics_bbs_member_id: member.id,
      ip: props.body.ip ?? "0.0.0.0", // Use provided IP or fallback
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(new Date()),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Generate JWT tokens with exact payload structure
  const token = {
    access: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  } as IAuthorizationToken;

  // Return authorized member data
  return {
    id: member.id,
    username: member.username,
    password_hash: member.password_hash,
    email: member.email,
    created_at: toISOStringSafe(member.created_at),
    updated_at: toISOStringSafe(member.updated_at),
    deleted_at: member.deleted_at
      ? toISOStringSafe(member.deleted_at)
      : undefined,
    role: "member" as const,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthModeratorLogin(props: {
  body: IPoliticsBbsModerator.ILogin;
}): Promise<IPoliticsBbsModerator.IAuthorized> {
  // Step 1: Find moderator by username or email
  const moderator = await MyGlobal.prisma.politics_bbs_moderators.findFirst({
    where: {
      OR: [
        { username: props.body.username_or_email },
        { email: props.body.username_or_email },
      ],
      deleted_at: null, // Don't find soft-deleted accounts
    },
  });

  // Validate moderator exists
  if (!moderator) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Step 2: Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    moderator.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Step 3: Create new session record - MUST provide explicit id
  const accessExpires = new Date(Date.now() + 15 * 60 * 1000); // 15 minutes
  const refreshExpires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days
  const sessionId = v4();

  await MyGlobal.prisma.politics_bbs_moderator_sessions.create({
    data: {
      id: sessionId,
      politics_bbs_moderator_id: moderator.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(new Date()),
      expired_at: null,
    },
  });

  // Step 4: Generate JWT tokens
  const accessToken = jwt.sign(
    {
      type: "moderator",
      id: moderator.id,
      session_id: sessionId,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "15m",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "moderator",
      id: moderator.id,
      session_id: sessionId,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "30d",
      issuer: "autobe",
    },
  );

  const authorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Step 5: Return authorized moderator with token
  return {
    id: moderator.id,
    username: moderator.username,
    email: moderator.email,
    created_at: toISOStringSafe(
      moderator.created_at,
    ) satisfies string as string,
    updated_at: toISOStringSafe(
      moderator.updated_at,
    ) satisfies string as string,
    deleted_at: moderator.deleted_at
      ? toISOStringSafe(moderator.deleted_at)
      : undefined,
    token: authorizationToken,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putAuthModeratorPassword(props: {
  moderator: ModeratorPayload;
  body: IPoliticsBbsModerator.IPassword;
}): Promise<IPoliticsBbsModerator.IAuthorized> {
  const { moderator, body } = props;

  // Verify moderator still exists and is not soft-deleted
  const existingModerator =
    await MyGlobal.prisma.politics_bbs_moderators.findFirst({
      where: {
        id: moderator.id,
        deleted_at: null,
      },
    });

  if (!existingModerator) {
    throw new HttpException("Moderator not found", 404);
  }

  // Hash the new password
  const passwordHash = await PasswordUtil.hash(body.password);

  // Update moderator password and timestamp
  const updatedModerator = await MyGlobal.prisma.politics_bbs_moderators.update(
    {
      where: { id: moderator.id },
      data: {
        password_hash: passwordHash,
        updated_at: toISOStringSafe(new Date()),
      },
    },
  );

  // Generate new tokens for session continuation
  const accessToken = jwt.sign(
    {
      id: updatedModerator.id,
      type: "moderator",
      session_id: moderator.session_id,
    } as ModeratorPayload,
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h" },
  );

  const refreshToken = jwt.sign(
    {
      id: updatedModerator.id,
      type: "moderator",
      session_id: moderator.session_id,
    } as ModeratorPayload,
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "30d" },
  );

  // Return complete moderator profile with new tokens
  return {
    id: updatedModerator.id satisfies string as string,
    username: updatedModerator.username,
    email: updatedModerator.email,
    created_at: toISOStringSafe(
      updatedModerator.created_at,
    ) satisfies string as string,
    updated_at: toISOStringSafe(
      updatedModerator.updated_at,
    ) satisfies string as string,
    deleted_at: updatedModerator.deleted_at
      ? toISOStringSafe(updatedModerator.deleted_at)
      : null,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(new Date(Date.now() + 3600 * 1000)),
      refreshable_until: toISOStringSafe(
        new Date(Date.now() + 30 * 24 * 3600 * 1000),
      ),
    } as IAuthorizationToken,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticle";
import { IPoliticsBbsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsCategory";
import { IPoliticsBbsArticleSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticleSnapshot";
import { IPoliticsBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsComment";
import { IPoliticsBbsFileAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsFileAttachment";
import { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";
import { IPoliticsBbsImageAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsImageAttachment";
import { IPoliticsBbsAttachmentOfVisitor } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfVisitor";
import { IPoliticsBbsVisitor } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsVisitor";
import { IPoliticsBbsAttachmentOfMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfMember";
import { IPoliticsBbsAttachmentOfModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsAttachmentOfModerator";
import { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putPoliticsBbsMemberArticlesArticleId(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  body: IPoliticsBbsArticle.IUpdate;
}): Promise<IPoliticsBbsArticle> {
  const { member, articleId, body } = props;

  // Authorization: Ensure member exists and is not deleted
  await MyGlobal.prisma.politics_bbs_members.findUniqueOrThrow({
    where: {
      id: member.id,
      deleted_at: null,
    },
  });

  // Fetch article and verify ownership
  const article = await MyGlobal.prisma.politics_bbs_articles.findUniqueOrThrow(
    {
      where: { id: articleId },
    },
  );

  if (article.politics_bbs_creator_id !== member.id) {
    throw new HttpException("Only article creators can edit articles", 403);
  }

  // Check 24-hour editing window
  const currentTime = toISOStringSafe(new Date());
  const hoursSinceCreation =
    (Date.parse(currentTime) -
      Date.parse(toISOStringSafe(article.created_at))) /
    (1000 * 60 * 60);

  if (hoursSinceCreation > 24) {
    throw new HttpException(
      "Articles can only be edited within 24 hours of creation",
      403,
    );
  }

  // Create snapshot for audit trail
  const snapshotData = {
    id: v4() as string & tags.Format<"uuid">,
    politics_bbs_article_id: articleId,
    title: article.title,
    content: article.content,
    state: article.state,
    view_count: article.view_count,
    created_at: currentTime,
  };

  await MyGlobal.prisma.politics_bbs_article_snapshots.create({
    data: snapshotData,
  });

  // Update article with partial data support
  const updated = await MyGlobal.prisma.politics_bbs_articles.update({
    where: { id: articleId },
    data: {
      title: body.title ?? undefined,
      content: body.content ?? undefined,
      politics_bbs_category_id: body.politics_bbs_category_id ?? undefined,
      updated_at: currentTime,
    },
  });

  // Return article with proper type conversion
  return {
    id: updated.id,
    politics_bbs_category_id: updated.politics_bbs_category_id,
    politics_bbs_creator_id: updated.politics_bbs_creator_id,
    title: updated.title,
    content: updated.content,
    state: updated.state,
    view_count: updated.view_count,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsModerationReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerationReview";
import { IPageIPoliticsBbsModerationReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoliticsBbsModerationReview";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchPoliticsBbsModeratorModeratorContentReview(props: {
  moderator: ModeratorPayload;
  body: IPoliticsBbsModerationReview.IRequest;
}): Promise<IPageIPoliticsBbsModerationReview.ISummary> {
  const { body } = props;

  // Extract pagination parameters
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Build base where conditions for articles requiring review
  const articleWhere = {
    deleted_at: null,
    state: { in: body.statuses },
    ...(body.categoryCode !== undefined &&
      body.categoryCode !== null && {
        category: {
          code: body.categoryCode,
          deleted_at: null,
        },
      }),
    ...(body.createdAfter !== undefined &&
      body.createdAfter !== null && {
        created_at: { gte: body.createdAfter },
      }),
    ...(body.createdBefore !== undefined &&
      body.createdBefore !== null && {
        created_at: { lte: body.createdBefore },
      }),
    ...(body.search && {
      OR: [
        { title: { contains: body.search } },
        { content: { contains: body.search } },
        { creator: { username: { contains: body.search } } },
      ],
    }),
  };

  // Build base where conditions for comments requiring review
  const commentWhere = {
    deleted_at: null,
    status: { in: body.statuses },
    NOT: { actor_type: "moderator" }, // Exclude moderator comments from review
    ...(body.createdAfter !== undefined &&
      body.createdAfter !== null && {
        created_at: { gte: body.createdAfter },
      }),
    ...(body.createdBefore !== undefined &&
      body.createdBefore !== null && {
        created_at: { lte: body.createdBefore },
      }),
    ...(body.search && {
      OR: [
        { content: { contains: body.search } },
        {
          article: {
            OR: [
              { title: { contains: body.search } },
              { creator: { username: { contains: body.search } } },
            ],
          },
        },
      ],
    }),
  };

  // Determine content type filtering strategy
  const fetchArticles =
    body.contentType === "article" || body.contentType === "all";
  const fetchComments =
    body.contentType === "comment" || body.contentType === "all";

  let articles: any[] = [];
  let comments: any[] = [];
  let articleCount = 0;
  let commentCount = 0;

  // Fetch articles pending review
  if (fetchArticles) {
    [articles, articleCount] = await Promise.all([
      MyGlobal.prisma.politics_bbs_articles.findMany({
        where: articleWhere,
        include: {
          category: {
            select: { id: true, name: true, code: true },
          },
          creator: {
            select: { id: true, username: true },
          },
        },
        orderBy: { created_at: "desc" },
      }),
      MyGlobal.prisma.politics_bbs_articles.count({ where: articleWhere }),
    ]);
  }

  // Fetch comments pending review
  if (fetchComments) {
    [comments, commentCount] = await Promise.all([
      MyGlobal.prisma.politics_bbs_comments.findMany({
        where: commentWhere,
        include: {
          article: {
            select: {
              id: true,
              title: true,
              creator: {
                select: { id: true, username: true },
              },
            },
          },
        },
        orderBy: { created_at: "desc" },
      }),
      MyGlobal.prisma.politics_bbs_comments.count({ where: commentWhere }),
    ]);
  }

  // Create moderation review summaries for articles
  const articleSummaries: IPoliticsBbsModerationReview.ISummary[] =
    articles.map((article) => ({
      id: v4() as string & tags.Format<"uuid">, // Generate review ID
      politics_bbs_article_snapshot_id: article.id,
      politics_bbs_moderator_id: props.moderator.id satisfies string as string,
      title: article.title,
      reason_code: "ARTICLE_" + article.state.replace(/_/g, "").toUpperCase(),
      status: article.state as
        | "pending"
        | "approved"
        | "rejected"
        | "appealed"
        | "dismissed",
      previous_status: null, // No previous status recorded
      created_at: toISOStringSafe(article.created_at),
    }));

  // Create moderation review summaries for comments
  const commentSummaries: IPoliticsBbsModerationReview.ISummary[] =
    comments.map((comment) => ({
      id: v4() as string & tags.Format<"uuid">, // Generate review ID
      politics_bbs_article_snapshot_id: comment.article.id,
      politics_bbs_moderator_id: props.moderator.id satisfies string as string,
      title: `Comment on "${comment.article.title}" by ${comment.actor_type}`,
      reason_code: "COMMENT_" + comment.status.replace(/_/g, "").toUpperCase(),
      status: comment.status as
        | "pending"
        | "approved"
        | "rejected"
        | "appealed"
        | "dismissed",
      previous_status: null, // No previous status recorded
      created_at: toISOStringSafe(comment.created_at),
    }));

  // Combine and sort all reviewed items by creation date (newest first)
  const allItems = [...articleSummaries, ...commentSummaries].sort(
    (a, b) =>
      new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
  );

  // Apply pagination to the combined results
  const startIndex = skip;
  const endIndex = startIndex + limit;
  const paginatedItems = allItems.slice(startIndex, endIndex);
  const totalCount = articleCount + commentCount;
  const totalPages = Math.ceil(totalCount / limit);

  return {
    pagination: {
      current: Number(page) as number & tags.Type<"int32"> & tags.Minimum<0>,
      limit: Number(limit) as number & tags.Type<"int32"> & tags.Minimum<0>,
      records: totalCount as number & tags.Type<"int32"> & tags.Minimum<0>,
      pages: totalPages as number & tags.Type<"int32"> & tags.Minimum<0>,
    },
    data: paginatedItems,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMembersJoin(props: {
  body: IPoliticsBbsMember.IJoin;
}): Promise<IPoliticsBbsMember.IAuthorized> {
  // Check for duplicate username
  const existing = await MyGlobal.prisma.politics_bbs_members.findFirst({
    where: {
      OR: [{ username: props.body.username }, { email: props.body.email }],
    },
  });

  if (existing) {
    throw new HttpException("Username or email already registered", 409);
  }

  // Hash password securely
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Create member record - ID has no @default() so must provide v4()
  const memberId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  const member = await MyGlobal.prisma.politics_bbs_members.create({
    data: {
      id: memberId,
      username: props.body.username,
      email: props.body.email,
      password_hash: hashedPassword,
      created_at: now,
      updated_at: now,
      // deleted_at defaults to null/nullable for new accounts
    },
  });

  // Create session record for authentication tracking
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const sessionId = v4() as string & tags.Format<"uuid">;
  const sessionExpires = toISOStringSafe(accessExpires);
  const refreshUntil = toISOStringSafe(refreshExpires);

  await MyGlobal.prisma.politics_bbs_member_sessions.create({
    data: {
      id: sessionId,
      politics_bbs_member_id: memberId,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: sessionExpires,
    },
  });

  // Generate JWT tokens with exact payload structure
  const accessToken = jwt.sign(
    {
      type: "member",
      id: memberId,
      session_id: sessionId,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "member",
      id: memberId,
      session_id: sessionId,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Return authorized member with JWT tokens
  return {
    id: memberId,
    username: member.username,
    email: member.email,
    created_at: now,
    updated_at: now,
    deleted_at: member.deleted_at
      ? (toISOStringSafe(member.deleted_at) satisfies string as string)
      : undefined,
    role: "member",
    password_hash: hashedPassword,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: sessionExpires,
      refreshable_until: refreshUntil,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthModeratorJoin(props: {
  body: IPoliticsBbsModerator.ICreate;
}): Promise<IPoliticsBbsModerator.IAuthorized> {
  // Check for duplicate username
  const existingUsername =
    await MyGlobal.prisma.politics_bbs_moderators.findFirst({
      where: { username: props.body.username },
      select: { id: true },
    });
  if (existingUsername) {
    throw new HttpException("Username already exists", 409);
  }

  // Check for duplicate email
  const existingEmail = await MyGlobal.prisma.politics_bbs_moderators.findFirst(
    {
      where: { email: props.body.email },
      select: { id: true },
    },
  );
  if (existingEmail) {
    throw new HttpException("Email already exists", 409);
  }

  // Hash password using PasswordUtil
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 15 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
  );

  // Create moderator account with explicit ID (no @default in schema)
  const moderator = await MyGlobal.prisma.politics_bbs_moderators.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      username: props.body.username,
      password_hash: hashedPassword,
      email: props.body.email,
      created_at: now as string & tags.Format<"date-time">,
      updated_at: now as string & tags.Format<"date-time">,
    },
  });

  // Create session record
  const session = await MyGlobal.prisma.politics_bbs_moderator_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      politics_bbs_moderator_id: moderator.id,
      ip: "127.0.0.1", // Should be extracted from headers in real implementation
      href: "",
      referrer: "",
      created_at: toISOStringSafe(new Date()),
      expired_at: accessExpires,
    },
  });

  // Generate JWT tokens with exact payload structure
  const accessToken = jwt.sign(
    {
      type: "moderator",
      id: moderator.id,
      session_id: session.id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "15m", issuer: "autobe" },
  );

  const refreshToken = jwt.sign(
    {
      type: "moderator",
      id: moderator.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "30d", issuer: "autobe" },
  );

  const token = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  } satisfies IAuthorizationToken;

  const response = {
    id: moderator.id,
    username: moderator.username,
    email: moderator.email,
    created_at: toISOStringSafe(
      moderator.created_at,
    ) satisfies string as string,
    updated_at: toISOStringSafe(
      moderator.updated_at,
    ) satisfies string as string,
    deleted_at: moderator.deleted_at
      ? (toISOStringSafe(moderator.deleted_at) satisfies string as string)
      : null,
    token,
  } satisfies IPoliticsBbsModerator.IAuthorized;

  return response;
}

