import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsComment";

export async function getPoliticsBbsCommentsCommentId(props: {
  commentId: string & tags.Format<"uuid">;
}): Promise<IPoliticsBbsComment> {
  const comment = await MyGlobal.prisma.politics_bbs_comments.findFirst({
    where: {
      id: props.commentId,
      deleted_at: null,
    },
  });

  if (!comment) {
    throw new HttpException("Comment not found", 404);
  }

  return {
    id: comment.id as string & tags.Format<"uuid">,
    politics_bbs_article_id: comment.politics_bbs_article_id,
    parent_id: comment.parent_id === null ? undefined : comment.parent_id,
    content: comment.content,
    depth: comment.depth as number & tags.Type<"int32">,
    status: comment.status,
    actor_type: comment.actor_type,
    created_at: comment.created_at.toISOString() as string &
      tags.Format<"date-time">,
    updated_at: comment.updated_at.toISOString() as string &
      tags.Format<"date-time">,
    deleted_at:
      comment.deleted_at === null
        ? (null as (string & tags.Format<"date-time">) | null)
        : (comment.deleted_at.toISOString() as string &
            tags.Format<"date-time">),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsComment";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchPoliticsBbsMemberCommentsCommentId(props: {
  member: MemberPayload;
  commentId: string & tags.Format<"uuid">;
  content: string & tags.MinLength<20> & tags.MaxLength<1000>;
  body: IPoliticsBbsComment.IUpdate;
}): Promise<IPoliticsBbsComment> {
  const { member, commentId, body } = props;

  // 1. Load comment with ownership via member subtype to validate ownership.
  const comment = await MyGlobal.prisma.politics_bbs_comments.findUnique({
    where: { id: commentId, deleted_at: null },
    include: { politics_bbs_comment_of_members: true },
  });

  if (!comment) {
    throw new HttpException("Comment not found", 404);
  }

  // 2. Validate ownership: Only allow if this member owns the comment.
  const memberOwnerRel = comment.politics_bbs_comment_of_members;
  if (!memberOwnerRel || memberOwnerRel.politics_bbs_member_id !== member.id) {
    throw new HttpException("You can only edit your own comments", 403);
  }

  const updatedAt = toISOStringSafe(new Date());

  // 3. Update comment content and timestamp.
  const updated = await MyGlobal.prisma.politics_bbs_comments.update({
    where: { id: commentId },
    data: {
      content: body.content,
      updated_at: updatedAt satisfies string & tags.Format<"date-time">,
    },
  });

  // 4. Return the updated comment matching IPoliticsBbsComment.
  return {
    id: updated.id as string & tags.Format<"uuid">,
    politics_bbs_article_id: updated.politics_bbs_article_id as string &
      tags.Format<"uuid">,
    parent_id:
      updated.parent_id === null
        ? undefined
        : (updated.parent_id as (string & tags.Format<"uuid">) | undefined),
    content: updated.content,
    depth: updated.depth as number & tags.Type<"int32">,
    status: updated.status,
    actor_type: updated.actor_type,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: updatedAt,
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
  } satisfies IPoliticsBbsComment;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function deletePoliticsBbsMemberCommentsCommentId(props: {
  member: MemberPayload;
  commentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { member, commentId } = props;

  // Validate comment ownership through member-specific subtype relationship
  const memberComment =
    await MyGlobal.prisma.politics_bbs_comment_of_members.findFirst({
      where: {
        politics_bbs_member_id: member.id,
        politics_bbs_comment_id: commentId,
      },
    });

  if (!memberComment) {
    throw new HttpException(
      "Unauthorized: You can only delete your own comments",
      403,
    );
  }

  // Check if comment exists and verify actor type
  const comment = await MyGlobal.prisma.politics_bbs_comments.findUniqueOrThrow(
    {
      where: { id: commentId },
    },
  );

  if (comment.actor_type !== "member") {
    throw new HttpException(
      "Forbidden: Cannot interact with non-member comments",
      403,
    );
  }

  // Perform soft delete - set deleted_at timestamp while preserving content
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.politics_bbs_comments.update({
    where: { id: commentId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsContentApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsContentApproval";
import { IPoliticsBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticle";
import { IPoliticsBbsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsCategory";
import { IPoliticsBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsComment";
import { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putPoliticsBbsModeratorModeratorContentContentIdApprove(props: {
  moderator: ModeratorPayload;
  contentId: string & tags.Format<"uuid">;
  body: IPoliticsBbsContentApproval.ICreate;
}): Promise<IPoliticsBbsContentApproval> {
  // First check if content exists as an article
  const article = await MyGlobal.prisma.politics_bbs_articles.findFirst({
    where: {
      id: props.contentId,
      deleted_at: null,
      state: "pending", // Only allow approval of pending content
    },
    include: {
      category: true,
    },
  });

  if (article) {
    const now = toISOStringSafe(new Date());

    // Update article to approved state
    const updatedArticle = await MyGlobal.prisma.politics_bbs_articles.update({
      where: { id: props.contentId },
      data: {
        state: "approved",
        updated_at: now,
      },
    });

    // Get moderator summary information
    const moderatorData =
      await MyGlobal.prisma.politics_bbs_moderators.findUniqueOrThrow({
        where: { id: props.moderator.id },
      });

    return {
      id: updatedArticle.id,
      state: "approved",
      contentType: {
        id: updatedArticle.id,
        title: updatedArticle.title,
        content: updatedArticle.content,
        state: updatedArticle.state,
        view_count: updatedArticle.view_count,
        created_at: toISOStringSafe(updatedArticle.created_at),
        updated_at: toISOStringSafe(updatedArticle.updated_at),
        category: {
          id: article.category.id,
          code: article.category.code,
          name: article.category.name,
          created_at: toISOStringSafe(article.category.created_at),
          updated_at: article.category.updated_at
            ? toISOStringSafe(article.category.updated_at)
            : null,
          deleted_at: article.category.deleted_at
            ? toISOStringSafe(article.category.deleted_at)
            : null,
          sequence: article.category.sequence,
          primary: article.category.primary,
          required: article.category.required,
          multiplicative: article.category.multiplicative,
          color: article.category.color,
          icon: article.category.icon,
          description: article.category.description,
        },
      },
      moderator: {
        id: moderatorData.id,
        username: moderatorData.username,
        email: moderatorData.email,
        created_at: toISOStringSafe(moderatorData.created_at),
      },
      notes: props.body.notes,
      approvedAt: now,
    };
  }

  // If not found as article, check as comment
  const comment = await MyGlobal.prisma.politics_bbs_comments.findFirst({
    where: {
      id: props.contentId,
      deleted_at: null,
      status: "pending", // Only allow approval of pending content
    },
    include: {
      article: true,
    },
  });

  if (comment) {
    const now = toISOStringSafe(new Date());

    // Update comment to approved status
    const updatedComment = await MyGlobal.prisma.politics_bbs_comments.update({
      where: { id: props.contentId },
      data: {
        status: "approved",
        updated_at: now,
      },
    });

    // Get moderator summary information
    const moderatorData =
      await MyGlobal.prisma.politics_bbs_moderators.findUniqueOrThrow({
        where: { id: props.moderator.id },
      });

    return {
      id: updatedComment.id,
      state: "approved",
      contentType: {
        id: updatedComment.id,
        politics_bbs_article_id: updatedComment.politics_bbs_article_id,
        parent_id: updatedComment.parent_id
          ? updatedComment.parent_id
          : undefined,
        content: updatedComment.content,
        depth: updatedComment.depth,
        status: updatedComment.status,
        actor_type: updatedComment.actor_type,
        created_at: toISOStringSafe(updatedComment.created_at),
      },
      moderator: {
        id: moderatorData.id,
        username: moderatorData.username,
        email: moderatorData.email,
        created_at: toISOStringSafe(moderatorData.created_at),
      },
      notes: props.body.notes,
      approvedAt: now,
    };
  }

  throw new HttpException("Content not found or already processed", 404);
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsContentReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsContentReview";
import { IPageIPoliticsBbsContentReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoliticsBbsContentReview";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPoliticsBbsArticleCreator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticleCreator";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchPoliticsBbsModeratorContentReview(props: {
  moderator: ModeratorPayload;
  body: IPoliticsBbsContentReview.IRequest;
}): Promise<IPageIPoliticsBbsContentReview.ISummary> {
  const {
    page,
    limit,
    contentType = "all",
    statuses,
    search = "",
    categoryCode,
    createdAfter,
    createdBefore,
  } = props.body;

  // Validate pagination
  if (page < 1 || limit < 1 || limit > 100) {
    throw new HttpException("Invalid pagination parameters", 400);
  }

  const skip = (page - 1) * limit;
  const statusSet = new Set(statuses);

  // Build where conditions
  const articleWhere: Record<string, unknown> = {
    deleted_at: null,
    ...(contentType !== "comment" && {
      ...(statusSet.has("pending") && { state: "pending" }),
    }),
  };

  const commentWhere: Record<string, unknown> = {
    deleted_at: null,
    ...(contentType !== "article" && {
      ...(statusSet.has("pending") && { status: "pending" }),
      ...(statusSet.has("flagged") && { status: "flagged" }),
    }),
  };

  // Apply search filter
  if (search && search.length > 0) {
    articleWhere.OR = [
      { title: { contains: search } },
      { content: { contains: search } },
    ];
    commentWhere.OR = [{ content: { contains: search } }];
  }

  // Apply category filter for articles
  if (categoryCode && contentType !== "comment") {
    const category = await MyGlobal.prisma.politics_bbs_categories.findUnique({
      where: { code: categoryCode },
    });
    if (category) {
      articleWhere.politics_bbs_category_id = category.id;
    }
  }

  // Apply date filters
  if (createdAfter || createdBefore) {
    if (createdAfter) {
      articleWhere.created_at = { gte: createdAfter };
      commentWhere.created_at = { gte: createdAfter };
    }
    if (createdBefore) {
      articleWhere.created_at = articleWhere.created_at || {};
      commentWhere.created_at = commentWhere.created_at || {};
      (articleWhere.created_at as Record<string, unknown>).lte = createdBefore;
      (commentWhere.created_at as Record<string, unknown>).lte = createdBefore;
    }
  }

  // Fetch results in parallel
  const [articles, articleCount, comments, commentCount] = await Promise.all([
    contentType !== "comment"
      ? MyGlobal.prisma.politics_bbs_articles.findMany({
          where: articleWhere,
          include: {
            category: { select: { id: true, code: true, name: true } },
            creator: { select: { id: true, username: true, created_at: true } },
          },
          orderBy: { created_at: "desc" },
          skip,
          take: limit,
        })
      : [],

    contentType !== "comment"
      ? MyGlobal.prisma.politics_bbs_articles.count({
          where: articleWhere,
        })
      : 0,

    contentType !== "article"
      ? MyGlobal.prisma.politics_bbs_comments.findMany({
          where: commentWhere,
          include: {
            article: {
              select: {
                id: true,
                title: true,
                politics_bbs_category_id: true,
                creator: {
                  select: { id: true, username: true, created_at: true },
                },
              },
            },
          },
          orderBy: { created_at: "desc" },
          skip,
          take: limit,
        })
      : [],

    contentType !== "article"
      ? MyGlobal.prisma.politics_bbs_comments.count({
          where: commentWhere,
        })
      : 0,
  ]);

  // Process articles
  const articleReviews: IPoliticsBbsContentReview.ISummary[] = articles.map(
    (article) => ({
      id: article.id,
      politics_bbs_article_id: article.id,
      politics_bbs_category_id: article.category.id,
      category_code: article.category.code,
      category_name: article.category.name,
      article_title: article.title,
      article_creator: {
        id: article.creator.id,
        username: article.creator.username,
        account_type: "member",
        created_at: toISOStringSafe(article.creator.created_at),
      },
      review_type: "initial_submission",
      priority: "normal",
      violations: [],
      status: article.state,
      reviewed_by: null,
      created_at: toISOStringSafe(article.created_at),
      updated_at: toISOStringSafe(article.updated_at),
      expires_at: toISOStringSafe(new Date(Date.now() + 24 * 60 * 60 * 1000)),
    }),
  );

  // Process comments
  const commentReviews: IPoliticsBbsContentReview.ISummary[] = comments.map(
    (comment) => ({
      id: comment.id,
      politics_bbs_article_id: comment.article.id,
      politics_bbs_category_id: comment.article.politics_bbs_category_id,
      category_code: "unknown",
      category_name: "Unknown",
      article_title: comment.article.title,
      article_creator: {
        id: comment.article.creator?.id ?? v4(),
        username: comment.article.creator?.username ?? "Unknown",
        account_type: "member",
        created_at: toISOStringSafe(
          comment.article.creator?.created_at ?? new Date(),
        ),
      },
      review_type: "community_flagged",
      priority: comment.status === "flagged" ? "urgent" : "normal",
      violations: [],
      status: comment.status,
      reviewed_by: null,
      created_at: toISOStringSafe(comment.created_at),
      updated_at: toISOStringSafe(comment.updated_at),
      expires_at: toISOStringSafe(new Date(Date.now() + 6 * 60 * 60 * 1000)),
    }),
  );

  // Combine results
  const data = [...articleReviews, ...commentReviews];

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: Number(articleCount + commentCount),
      pages: Number(Math.ceil((articleCount + commentCount) / limit)),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPoliticsBbsContentApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsContentApproval";
import { IPoliticsBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsArticle";
import { IPoliticsBbsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsCategory";
import { IPoliticsBbsComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsComment";
import { IPoliticsBbsModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoliticsBbsModerator";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putPoliticsBbsModeratorContentContentIdApprove(props: {
  moderator: ModeratorPayload;
  contentId: string & tags.Format<"uuid">;
  body: IPoliticsBbsContentApproval.ICreate;
}): Promise<IPoliticsBbsContentApproval> {
  // Fetch moderator details for the response
  const moderatorRecord =
    await MyGlobal.prisma.politics_bbs_moderators.findUniqueOrThrow({
      where: {
        id: props.moderator.id,
        deleted_at: null,
      },
    });

  // Try to approve as article first
  const articleResult = await MyGlobal.prisma.politics_bbs_articles.findUnique({
    where: {
      id: props.contentId,
      deleted_at: null,
    },
  });

  if (articleResult) {
    if (articleResult.state !== "pending") {
      throw new HttpException(
        `Article is not in pending state (current: ${articleResult.state})`,
        400,
      );
    }

    const updatedArticle = await MyGlobal.prisma.politics_bbs_articles.update({
      where: { id: props.contentId },
      data: {
        state: "approved",
        updated_at: toISOStringSafe(new Date()),
      },
    });

    const category =
      await MyGlobal.prisma.politics_bbs_categories.findUniqueOrThrow({
        where: { id: updatedArticle.politics_bbs_category_id },
      });

    return {
      id: updatedArticle.id,
      state: "approved",
      contentType: {
        id: updatedArticle.id,
        title: updatedArticle.title,
        content: updatedArticle.content,
        state: updatedArticle.state,
        view_count: updatedArticle.view_count,
        created_at: toISOStringSafe(updatedArticle.created_at),
        updated_at: toISOStringSafe(updatedArticle.updated_at),
        category: {
          id: category.id,
          code: category.code,
          name: category.name,
          created_at: toISOStringSafe(category.created_at),
          updated_at: category.updated_at
            ? toISOStringSafe(category.updated_at)
            : null,
          deleted_at: category.deleted_at
            ? toISOStringSafe(category.deleted_at)
            : null,
          sequence: category.sequence,
          primary: category.primary,
          required: category.required,
          multiplicative: category.multiplicative,
          color: category.color,
          icon: category.icon,
          description: category.description,
        },
      },
      moderator: {
        id: moderatorRecord.id,
        username: moderatorRecord.username,
        email: moderatorRecord.email,
        created_at: toISOStringSafe(moderatorRecord.created_at),
      },
      notes: props.body.notes,
      approvedAt: toISOStringSafe(new Date()),
    };
  }

  // Try to approve as comment
  const commentResult = await MyGlobal.prisma.politics_bbs_comments.findUnique({
    where: {
      id: props.contentId,
      deleted_at: null,
    },
  });

  if (commentResult) {
    if (commentResult.status !== "pending") {
      throw new HttpException(
        `Comment is not in pending status (current: ${commentResult.status})`,
        400,
      );
    }

    const updatedComment = await MyGlobal.prisma.politics_bbs_comments.update({
      where: { id: props.contentId },
